import registry from "./registry.js";
const nodesByType = new Map(registry.nodes.map((node) => [node.type_id.toLowerCase(), node]));
/**
 * Return the baked node registry (read-only).
 */
export function getNodeRegistry() {
    return registry;
}
/**
 * Lookup a node signature by type id.
 */
export function findNodeSignature(typeId) {
    return nodesByType.get(typeId.toString().toLowerCase());
}
/**
 * Get a node signature or throw if it is missing.
 */
export function requireNodeSignature(typeId) {
    const entry = findNodeSignature(typeId);
    if (!entry) {
        throw new Error(`Unknown node type '${typeId}' in registry.`);
    }
    return entry;
}
/**
 * List all node type identifiers available in the registry.
 */
export function listNodeTypeIds() {
    return registry.nodes.map((node) => node.type_id);
}
/**
 * List the node signatures grouped by category.
 */
export function groupNodeSignaturesByCategory() {
    const map = new Map();
    for (const node of registry.nodes) {
        const key = (node.category || "uncategorized").toLowerCase();
        const existing = map.get(key);
        if (existing) {
            existing.push(node);
        }
        else {
            map.set(key, [node]);
        }
    }
    return map;
}
export const nodeRegistryVersion = registry.version;
